namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        ProcessItems(items, settlementCurrency, percentageFee, fixedFee, submissionLimit, lines, accepted, seen);
        return CompleteSettlement(merchantId, settlementCurrency, gateway, lines, accepted);
    }

    private static void ProcessItems(IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, HashSet<string> seen)
    {
        foreach (var item in items)
        {
            var rejectionStatus = GetItemRejectionStatus(item, settlementCurrency, seen);
            if (rejectionStatus is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionStatus));
                continue;
            }

            var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
            var net = decimal.Round(item.GrossAmount - fee, 2);
            rejectionStatus = GetNetRejectionStatus(net, submissionLimit, accepted);
            if (rejectionStatus is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionStatus));
                continue;
            }

            accepted.Add((item.Reference, net));
        }
    }

    private static string? GetItemRejectionStatus(PaymentItem item, string settlementCurrency,
        HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static string? GetNetRejectionStatus(decimal net, decimal submissionLimit,
        List<(string Reference, decimal Net)> accepted)
    {
        if (net <= 0m)
            return "fee-exceeds-amount";
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            return "batch-limit";

        return null;
    }

    private static SettlementResult CompleteSettlement(string merchantId, string settlementCurrency,
        ISettlementGateway gateway, List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted)
    {
        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");
        if (string.IsNullOrWhiteSpace(merchantId))
            return CreateRejectedResult(lines, accepted, "invalid-merchant");

        var total = accepted.Sum(entry => entry.Net);
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total,
            accepted.Select(entry => entry.Reference).ToArray());
        if (!gatewayResult.Accepted)
            return CreateRejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        return new SettlementResult(lines, total,
            lines.Any(line => line.Status != "submitted") ? "partial" : "submitted");
    }

    private static SettlementResult CreateRejectedResult(List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, string status)
    {
        return new SettlementResult(
            [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, status))],
            0m,
            "rejected");
    }
}
